/* ============================================================
   Rapportini — gestionale lavori per idraulici
   Persistenza tramite localStorage del browser (i dati restano salvati su questo dispositivo).
   ============================================================ */

const K_CLIENTI = "idraulico_v1_clienti";
const K_RAPP = "idraulico_v1_rapportini";
const K_RICH = "idraulico_v1_richieste";
const K_SEED = "idraulico_v1_demo_seeded";
const K_AZIENDA = "idraulico_v1_azienda";
const K_FATTURE = "idraulico_v1_fatture";
const K_LICENZE = "idraulico_v1_licenze";
const K_APP = "idraulico_v1_appuntamenti";
const K_ORD = "idraulico_v1_ordini_materiale";

const hasStore = true;

// Mappa chiave -> collezione API
const COLL = { [K_CLIENTI]: "clienti", [K_RAPP]: "rapportini", [K_RICH]: "richieste", [K_FATTURE]: "fatture", [K_APP]: "appuntamenti", [K_ORD]: "ordini" };

async function apiGet(path) {
  const r = await fetch("/api" + path, { credentials: "include" });
  if (!r.ok) throw new Error("HTTP " + r.status);
  return r.json();
}
async function apiSend(path, method, body) {
  const r = await fetch("/api" + path, {
    method,
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: body == null ? undefined : JSON.stringify(body),
  });
  let d = null;
  try { d = await r.json(); } catch (e) {}
  return { ok: r.ok, status: r.status, data: d || {} };
}

async function loadArr(key) {
  const coll = COLL[key];
  if (!coll) return [];
  try {
    const d = await apiGet("/data/" + coll);
    return Array.isArray(d.items) ? d.items : [];
  } catch (e) {
    return [];
  }
}
let _pendingSaves = 0;
const _saveSubs = new Set();
function _emitSave() { const s = _pendingSaves > 0; _saveSubs.forEach((fn) => { try { fn(s); } catch (e) {} }); }
function onSaveState(fn) { _saveSubs.add(fn); return () => _saveSubs.delete(fn); }

async function saveArr(key, val) {
  _pendingSaves++; _emitSave();
  try {
    if (key === K_AZIENDA) {
      await apiSend("/azienda", "PUT", val || {});
    } else {
      const coll = COLL[key];
      if (coll) await apiSend("/data/" + coll, "PUT", { items: val || [] });
    }
  } catch (e) {
  } finally {
    _pendingSaves--; _emitSave();
  }
}
async function loadObj(key) {
  if (key === K_AZIENDA) {
    try {
      const d = await apiGet("/azienda");
      const az = d.azienda || null;
      if (az && !az.denominazione && !az.partitaIva) return null;
      return az;
    } catch (e) {
      return null;
    }
  }
  return null;
}

const uid = () =>
  typeof crypto !== "undefined" && crypto.randomUUID
    ? crypto.randomUUID()
    : "id" + Date.now() + Math.random().toString(16).slice(2);

const eur = new Intl.NumberFormat("it-IT", { style: "currency", currency: "EUR" });
const fmtMoney = (n) => eur.format(n || 0);
const fmtDate = (iso) => {
  if (!iso) return "";
  const d = new Date(iso);
  if (isNaN(d)) return iso;
  return d.toLocaleDateString("it-IT", { day: "2-digit", month: "2-digit", year: "numeric" });
};
const todayISO = () => new Date().toISOString().slice(0, 10);
const numOrNull = (v) => {
  if (v === "" || v === null || v === undefined) return null;
  const n = Number(String(v).replace(",", "."));
  return isNaN(n) ? null : n;
};

const nomeCliente = (c) => {
  if (!c) return "Cliente eliminato";
  if (c.tipo === "azienda") return c.denominazione || c.nome || "";
  const full = [c.nome, c.cognome].filter(Boolean).join(" ");
  return full || c.denominazione || c.nome || "";
};
const indirizzoCliente = (c) => {
  if (!c) return "";
  const locProv = ([c.cap, c.comune].filter(Boolean).join(" ") + (c.provincia ? ` (${c.provincia})` : "")).trim();
  return [c.indirizzo, locProv].filter((s) => s && s.trim()).join(", ");
};

const importoRapp = (r) => {
  const mano = (Number(r.ore) || 0) * (Number(r.tariffaOraria) || 0);
  const art = (r.articoli || []).reduce((s, a) => s + (Number(a.prezzo) || 0), 0);
  return mano + art;
};
const haValore = (r) =>
  (Number(r.tariffaOraria) || 0) > 0 || (r.articoli || []).some((a) => (Number(a.prezzo) || 0) > 0);

/* ---------- export ---------- */

function download(filename, content, mime) {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const slug = (s) => String(s || "cliente").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

