function buildCsv(cliente, rapportini) {
  const sep = ";";
  const q = (v) => `"${String(v ?? "").replace(/"/g, '""')}"`;
  const head = [
    "Cliente",
    "P.IVA/CF",
    "Data",
    "Luogo",
    "Descrizione",
    "Ore",
    "Tariffa oraria",
    "Articoli",
    "Importo",
  ];
  const lines = [head.map(q).join(sep)];
  rapportini.forEach((r) => {
    const arts = (r.articoli || [])
      .map((a) => a.descrizione + ((Number(a.prezzo) || 0) > 0 ? " (" + fmtMoney(a.prezzo) + ")" : ""))
      .join(" | ");
    lines.push(
      [
        nomeCliente(cliente),
        cliente.piva || cliente.cf || "",
        fmtDate(r.data),
        r.luogo || "",
        r.descrizione || "",
        (Number(r.ore) || 0).toString().replace(".", ","),
        r.tariffaOraria ? String(r.tariffaOraria).replace(".", ",") : "",
        arts,
        haValore(r) ? fmtMoney(importoRapp(r)) : "",
      ]
        .map(q)
        .join(sep)
    );
  });
  return "\uFEFF" + lines.join("\r\n");
}

