export default function App() {
  const [loaded, setLoaded] = useState(false);
  useEffect(() => { try { document.documentElement.setAttribute("data-theme", "light"); } catch (e) {} }, []);
  const [publicView, setPublicView] = useState("landing"); // landing | login (quando non autenticato)
  const [demo, setDemo] = useState(false);
  const [clienti, setClienti] = useState([]);
  const [rapportini, setRapportini] = useState([]);
  const [richieste, setRichieste] = useState([]);
  const [azienda, setAzienda] = useState(null);
  const [fatture, setFatture] = useState([]);
  const [appuntamenti, setAppuntamenti] = useState([]);
  const [ordiniMateriale, setOrdiniMateriale] = useState([]);
  const [appForm, setAppForm] = useState(null); // appuntamento in modifica/creazione
  const [tab, setTab] = useState("rapportini");
  const [detailCliId, setDetailCliId] = useState(null);
  const [menuOpen, setMenuOpen] = useState(false);

  const [rappForm, setRappForm] = useState(null); // oggetto rapportino in modifica/creazione
  const [cliForm, setCliForm] = useState(null); // cliente in modifica/creazione (sezione clienti)
  const [richForm, setRichForm] = useState(null); // richiesta di assistenza in modifica/creazione
  const [aziendaForm, setAziendaForm] = useState(null); // form dati azienda (impostazioni)
  const [previewFattura, setPreviewFattura] = useState(null); // fattura in anteprima
  const [auth, setAuth] = useState(null); // sessione: null = login richiesto
  const [licenze, setLicenze] = useState([]);
  const [licenzeOpen, setLicenzeOpen] = useState(false);
  const [assistOpen, setAssistOpen] = useState(false);
  const [greet, setGreet] = useState(null);
  const [search, setSearch] = useState("");
  const [saving, setSaving] = useState(false);

  const caricaDati = async () => {
    let [c, r, ri] = await Promise.all([loadArr(K_CLIENTI), loadArr(K_RAPP), loadArr(K_RICH)]);
    let az = await loadObj(K_AZIENDA);
    if (az) {
      let changed = false;
      if (!Array.isArray(az.aliquoteIva)) { az = { ...az, aliquoteIva: Array.from(new Set([Number(az.aliquotaIva) || 22, 22, 10, 4])) }; changed = true; }
      if (az.aliquotaManodopera === undefined) { az = { ...az, aliquotaManodopera: Number(az.aliquotaIva) || 22, costoManodopera: az.costoManodopera ?? "", sezionale: az.sezionale ?? "" }; changed = true; }
      if (changed) saveArr(K_AZIENDA, az);
    }
    const ft = await loadArr(K_FATTURE);
    const ap = await loadArr(K_APP);
    const ordRaw = await loadArr(K_ORD);
    const SETT = 7 * 86400000;
    const ord = ordRaw.filter((o) => Date.now() - (o.createdAt || 0) < SETT);
    if (ord.length !== ordRaw.length) saveArr(K_ORD, ord); // auto-svuota i più vecchi di una settimana
    c = c.map(migrateCliente);
    setClienti(c);
    setRapportini(r);
    setRichieste(ri);
    setAzienda(az);
    setFatture(ft);
    setAppuntamenti(ap);
    setOrdiniMateriale(ord);
  };

  const boot = async (showGreet) => {
    let me = null;
    try {
      const r = await fetch("/api/me", { credentials: "include" });
      me = r.ok ? await r.json() : null;
    } catch (e) { me = null; }
    if (!me) { setAuth(null); setLoaded(true); return; }
    if (me.ruolo === "reseller") {
      setAuth({ role: "reseller", label: me.nome || "Rivenditore" });
      if (showGreet) setGreet("Benvenuto " + (me.nome || "Rivenditore"));
      setLoaded(true);
      return;
    }
    const nome = (me.azienda && me.azienda.denominazione) || me.email;
    setAuth({ role: "cliente", label: nome, scadenza: (me.azienda && me.azienda.licenza_scadenza) || null });
    if (showGreet) setGreet("Benvenuto " + nome);
    await caricaDati();
    setLoaded(true);
  };

  useEffect(() => { boot(false); }, []);
  useEffect(() => onSaveState(setSaving), []);

  const persistClienti = (next) => {
    setClienti(next);
    saveArr(K_CLIENTI, next);
  };
  const persistRapp = (next) => {
    setRapportini(next);
    saveArr(K_RAPP, next);
  };
  const persistRich = (next) => {
    setRichieste(next);
    saveArr(K_RICH, next);
  };
  const persistAzienda = (next) => {
    setAzienda(next);
    saveArr(K_AZIENDA, next);
  };
  const persistFatture = (next) => {
    setFatture(next);
    saveArr(K_FATTURE, next);
  };
  const deleteFattura = (id) => persistFatture(fatture.filter((f) => f.id !== id));

  const persistApp = (next) => { setAppuntamenti(next); saveArr(K_APP, next); };
  const emptyAppuntamento = () => ({ id: "", data: todayISO(), ora: "09:00", durata: 60, clienteId: "", clienteNome: "", titolo: "", luogo: "", note: "", stato: "da_fare", richiestaId: "" });
  const openNuovoApp = (prefill) => setAppForm({ ...emptyAppuntamento(), ...(prefill || {}) });
  const openEditApp = (a) => setAppForm({ ...a });
  const saveApp = () => {
    const f = appForm;
    if (!f || !(f.titolo || "").trim() || !f.data || !f.ora) return;
    const cli = f.clienteId ? clienti.find((c) => c.id === f.clienteId) : null;
    const rec = {
      id: f.id || uid(),
      data: f.data,
      ora: f.ora,
      durata: Number(f.durata) > 0 ? Number(f.durata) : 60,
      clienteId: f.clienteId || "",
      clienteNome: cli ? nomeCliente(cli) : (f.clienteNome || ""),
      titolo: f.titolo.trim(),
      luogo: (f.luogo || "").trim(),
      note: (f.note || "").trim(),
      stato: f.stato || "da_fare",
      richiestaId: f.richiestaId || "",
      createdAt: f.createdAt || Date.now(),
    };
    const exists = appuntamenti.some((a) => a.id === rec.id);
    persistApp(exists ? appuntamenti.map((a) => (a.id === rec.id ? rec : a)) : [...appuntamenti, rec]);
    setAppForm(null);
  };
  const deleteApp = (id) => { persistApp(appuntamenti.filter((a) => a.id !== id)); setAppForm(null); };
  const toggleApp = (id) => persistApp(appuntamenti.map((a) => (a.id === id ? { ...a, stato: a.stato === "fatto" ? "da_fare" : "fatto" } : a)));
  const pianificaDaRichiesta = (r) => {
    const cli = r.clienteId ? clienti.find((c) => c.id === r.clienteId) : null;
    setTab("agenda");
    openNuovoApp({
      clienteId: r.clienteId || "",
      clienteNome: cli ? nomeCliente(cli) : "",
      titolo: (r.descrizione || "").trim().slice(0, 80),
      note: r.descrizione || "",
      richiestaId: r.id || "",
      data: todayISO(),
    });
  };

  const SETTIMANA_MS = 7 * 86400000;
  const persistOrdini = (next) => { setOrdiniMateriale(next); saveArr(K_ORD, next); };
  const salvaOrdineMateriale = (order) => {
    const recenti = [order, ...ordiniMateriale].filter((o) => Date.now() - (o.createdAt || 0) < SETTIMANA_MS);
    persistOrdini(recenti);
  };

  const persistLicenze = (next) => { setLicenze(next); saveArr(K_LICENZE, next); };
  const tryLogin = async (email, pwd) => {
    const em = (email || "").trim().toLowerCase();
    const p = (pwd || "").trim();
    if (!em || !p) return "Inserisci email e password.";
    try {
      const r = await fetch("/api/login", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: em, password: p }),
      });
      const d = await r.json().catch(() => ({}));
      if (!r.ok) return d.error || "Email o password non corretti.";
    } catch (e) {
      return "Errore di connessione. Riprova.";
    }
    await boot(true);
    return null;
  };
  const tryRegister = async (denom, email, pwd) => {
    const d = (denom || "").trim();
    const em = (email || "").trim().toLowerCase();
    const p = (pwd || "").trim();
    if (!d || !em || p.length < 8) return "Inserisci denominazione, email e una password di almeno 8 caratteri.";
    try {
      const r = await fetch("/api/register", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ denominazione: d, email: em, password: p }),
      });
      const data = await r.json().catch(() => ({}));
      if (!r.ok) return data.error || "Registrazione non riuscita.";
    } catch (e) {
      return "Errore di connessione. Riprova.";
    }
    await boot(true);
    return null;
  };

  const logout = async () => {
    try { await fetch("/api/logout", { method: "POST", credentials: "include" }); } catch (e) {}
    setAuth(null); setGreet(null); setMenuOpen(false); setDetailCliId(null); setLicenzeOpen(false);
    setClienti([]); setRapportini([]); setRichieste([]); setFatture([]); setAzienda(null); setAppuntamenti([]); setOrdiniMateriale([]);
    setDemo(false); setPublicView("landing");
  };
  const startDemo = () => {
    setClienti(DEMO_CLIENTI.map(migrateCliente));
    setRapportini(DEMO_RAPP);
    setRichieste(DEMO_RICH);
    setAzienda(DEMO_AZIENDA);
    setFatture([]);
    setAppuntamenti(DEMO_APP);
    setOrdiniMateriale([]);
    setTab("rapportini");
    setDetailCliId(null);
    setDemo(true);
    setAuth({ role: "demo", label: "Demo", scadenza: null });
  };
  const exitDemo = () => {
    setDemo(false);
    setAuth(null);
    setClienti([]); setRapportini([]); setRichieste([]); setFatture([]); setAzienda(null); setAppuntamenti([]);
    setPublicView("login");
  };
  const createLicenza = (data) => {
    const mesi = Number(data.durataMesi) || 1;
    const d = new Date(); d.setMonth(d.getMonth() + mesi);
    persistLicenze([{ id: uid(), password: (data.password || "").trim(), nomeCliente: (data.nomeCliente || "").trim(), durataMesi: mesi, creataIl: Date.now(), scadenza: d.getTime() }, ...licenze]);
  };
  const deleteLicenza = (id) => persistLicenze(licenze.filter((l) => l.id !== id));
  const saveAzienda = () => {
    if (!aziendaForm.denominazione.trim()) return;
    const aliquote = Array.isArray(aziendaForm.aliquoteIva) && aziendaForm.aliquoteIva.length ? aziendaForm.aliquoteIva : [22];
    persistAzienda({
      ...aziendaForm,
      aliquotaIva: Number(aziendaForm.aliquotaIva) || 0,
      aliquoteIva: aliquote,
      costoManodopera: aziendaForm.costoManodopera === "" || aziendaForm.costoManodopera == null ? "" : Number(aziendaForm.costoManodopera) || 0,
      aliquotaManodopera: Number(aziendaForm.aliquotaManodopera) || 0,
      sezionale: (aziendaForm.sezionale || "").trim(),
      numeroProssimo: Number(aziendaForm.numeroProssimo) || 1,
    });
    setAziendaForm(null);
  };

  const generaXml = (cliente, selRapp, options) => {
    options = options || {};
    if (!azienda || !pivaCodice(azienda.partitaIva) || !azienda.denominazione.trim()) {
      setAziendaForm(azienda || emptyAzienda());
      return "Per generare la fattura XML servono i tuoi dati. Compila denominazione, P.IVA e indirizzo in “Dati azienda”, poi riprova.";
    }
    if (!selRapp.length) return null;
    const numero = Number(azienda.numeroProssimo) || 1;
    const progressivo = Number(azienda.progressivoInvio) || 1;
    const res = buildFatturaXML(azienda, cliente, selRapp, { numero, progressivo, modalitaPagamento: options.modalitaPagamento, sezionale: azienda.sezionale });
    if (res.lineCount === 0)
      return "Nessun importo da fatturare: imposta una tariffa oraria o un prezzo agli articoli dei rapportini selezionati, poi riprova.";
    download(res.filename, res.xml, "application/xml");
    persistAzienda({ ...azienda, numeroProssimo: numero + 1, progressivoInvio: progressivo + 1 });
    const rec = {
      id: uid(),
      numero: res.numero,
      filename: res.filename,
      data: res.data,
      clienteId: cliente.id,
      clienteNome: nomeCliente(cliente),
      imponibile: res.imponibile,
      imposta: res.imposta,
      bollo: res.bollo,
      totale: res.totale,
      riepiloghi: res.riepiloghi,
      modalitaPagamento: res.modalitaPagamento,
      regimeFiscale: azienda.regimeFiscale,
      righe: res.righe,
      cliente: { ...cliente },
      azienda: (() => { const { logo, ...rest } = azienda; return rest; })(),
      xml: res.xml,
      createdAt: Date.now(),
    };
    persistFatture([rec, ...fatture]);
    let msg = `Fattura n. ${res.numero} generata — file ${res.filename}, totale ${fmtMoney(res.totale)}. Salvata nella sezione Fatture. È una bozza: importala nel gestionale o controllala prima dell'invio allo SdI.`;
    if (res.warnings.length) msg += " Da verificare: " + res.warnings.join(" ");
    return msg;
  };

  const cliById = useMemo(() => Object.fromEntries(clienti.map((c) => [c.id, c])), [clienti]);
  const nextNumero = useMemo(
    () => (rapportini.reduce((m, r) => Math.max(m, r.numero || 0), 0) || 0) + 1,
    [rapportini]
  );
  const lastTariffa = useMemo(() => {
    const withRate = rapportini.filter((r) => r.tariffaOraria > 0).sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
    return withRate[0]?.tariffaOraria || "";
  }, [rapportini]);

  if (!loaded) return <div className="app"><Style /><div className="splash">Carico i dati…</div></div>;
  if (!auth) {
    if (publicView === "login") return <LoginScreen onSubmit={tryLogin} onRegister={tryRegister} onBack={() => setPublicView("landing")} />;
    return <Landing onLogin={() => setPublicView("login")} onDemo={startDemo} />;
  }
  if (auth.role === "reseller") return <ResellerScreen label={auth.label} onLogout={logout} />;

  /* ---- azioni rapportino ---- */
  const openNuovoRapp = () => {
    setRappForm({
      id: "",
      numero: nextNumero,
      clienteId: clienti[0]?.id || "",
      cliMode: clienti.length ? "existing" : "new",
      nuovoCli: emptyCliente(),
      data: todayISO(),
      luogo: "",
      descrizione: "",
      ore: "",
      tariffaOraria: Number(azienda?.costoManodopera) > 0 ? azienda.costoManodopera : lastTariffa,
      articoli: [],
      note: "",
      fatturato: false,
    });
  };
  const openEditRapp = (r) => {
    setRappForm({
      ...r,
      cliMode: "existing",
      nuovoCli: emptyCliente(),
      ore: r.ore ?? "",
      tariffaOraria: r.tariffaOraria ?? "",
      articoli: (r.articoli || []).map((a) => ({ ...a, prezzo: a.prezzo ?? "" })),
    });
  };

  const saveRapp = () => {
    const f = rappForm;
    let clienteId = f.clienteId;
    let newClienti = clienti;

    if (f.cliMode === "new") {
      const nc = { ...f.nuovoCli, id: uid() };
      if (!nomeCliente(nc).trim()) return;
      newClienti = [...clienti, nc];
      clienteId = nc.id;
    }
    if (!clienteId) return;

    const articoli = (f.articoli || [])
      .filter((a) => (a.descrizione || "").trim() || numOrNull(a.prezzo) !== null)
      .map((a) => ({ id: a.id || uid(), descrizione: a.descrizione || "", prezzo: numOrNull(a.prezzo), aliquota: a.aliquota === "" || a.aliquota === null || a.aliquota === undefined ? null : Number(a.aliquota) }));

    const rec = {
      id: f.id || uid(),
      numero: f.numero || nextNumero,
      clienteId,
      data: f.data || todayISO(),
      luogo: f.luogo || "",
      descrizione: f.descrizione || "",
      ore: numOrNull(f.ore) ?? 0,
      tariffaOraria: numOrNull(f.tariffaOraria) ?? 0,
      articoli,
      note: f.note || "",
      fatturato: !!f.fatturato,
      createdAt: f.createdAt || Date.now(),
    };

    if (newClienti !== clienti) persistClienti(newClienti);
    const exists = rapportini.some((r) => r.id === rec.id);
    persistRapp(exists ? rapportini.map((r) => (r.id === rec.id ? rec : r)) : [rec, ...rapportini]);
    setRappForm(null);
  };

  const deleteRapp = (id) => {
    persistRapp(rapportini.filter((r) => r.id !== id));
    setRappForm(null);
  };

  /* ---- azioni cliente ---- */
  const saveCli = () => {
    const f = cliForm;
    if (!nomeCliente(f).trim()) return;
    if (f.id) {
      persistClienti(clienti.map((c) => (c.id === f.id ? f : c)));
    } else {
      persistClienti([...clienti, { ...f, id: uid() }]);
    }
    setCliForm(null);
  };
  const deleteCli = (id) => {
    const n = rapportini.filter((r) => r.clienteId === id).length;
    if (n > 0 && !confirm(`Questo cliente ha ${n} rapportini collegati che verranno eliminati. Continuare?`)) return;
    persistClienti(clienti.filter((c) => c.id !== id));
    persistRapp(rapportini.filter((r) => r.clienteId !== id));
    setCliForm(null);
    setDetailCliId(null);
  };

  /* ---- azioni richieste assistenza ---- */
  const openNuovaRich = () =>
    setRichForm({
      id: "",
      clienteId: clienti[0]?.id || "",
      cliMode: clienti.length ? "existing" : "new",
      nuovoCli: emptyCliente(),
      data: todayISO(),
      descrizione: "",
      stato: "da_gestire",
    });
  const openEditRich = (ri) => setRichForm({ ...ri, cliMode: "existing", nuovoCli: emptyCliente() });

  const saveRich = () => {
    const f = richForm;
    let clienteId = f.clienteId;
    let newClienti = clienti;
    if (f.cliMode === "new") {
      const nc = { ...f.nuovoCli, id: uid() };
      if (!nomeCliente(nc).trim()) return;
      newClienti = [...clienti, nc];
      clienteId = nc.id;
    }
    if (!clienteId || !(f.descrizione || "").trim()) return;
    const rec = {
      id: f.id || uid(),
      clienteId,
      data: f.data || todayISO(),
      descrizione: f.descrizione.trim(),
      stato: f.stato || "da_gestire",
      createdAt: f.createdAt || Date.now(),
    };
    if (newClienti !== clienti) persistClienti(newClienti);
    const exists = richieste.some((r) => r.id === rec.id);
    persistRich(exists ? richieste.map((r) => (r.id === rec.id ? rec : r)) : [rec, ...richieste]);
    setRichForm(null);
  };
  const toggleRich = (id) =>
    persistRich(richieste.map((r) => (r.id === id ? { ...r, stato: r.stato === "svolto" ? "da_gestire" : "svolto" } : r)));
  const deleteRich = (id) => {
    persistRich(richieste.filter((r) => r.id !== id));
    setRichForm(null);
  };

  /* ============================================================ */

  return (
    <div className="app">
      <Style />

      <header className="topbar">
        <div className="topbar-in">
          <button className="icon-btn" onClick={() => setMenuOpen(true)} aria-label="Apri menu"><IcoMenu /></button>
          <div className="brand">
            <div className="brand-mark"><img src={ICON_INTERVENTIA} alt="interventia" /></div>
            <div className="brand-name">interventia</div>
          </div>
          <div className="topbar-spacer" />
          {saving && (
            <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, color: "var(--muted)", marginRight: 10 }}>
              <span style={{ width: 8, height: 8, borderRadius: "50%", background: "var(--petrol)", display: "inline-block" }} />
              Salvataggio…
            </span>
          )}
          <button className="btn btn-primary" onClick={openNuovoRapp}>＋ Nuovo rapportino</button>
        </div>
      </header>

      {demo && (
        <div className="demo-bar">
          <span>Stai guardando una <b>demo</b> con dati di esempio — le modifiche non vengono salvate.</span>
          <button className="btn btn-sm" onClick={exitDemo}>Accedi</button>
        </div>
      )}

      {auth.scadenza && (() => {
        const fine = new Date(auth.scadenza + "T23:59:59").getTime();
        const giorni = Math.ceil((fine - Date.now()) / 86400000);
        if (giorni > 14) return null;
        const urgente = giorni <= 3;
        return (
          <div style={{ background: urgente ? "var(--danger-soft)" : "var(--bg-tint)", borderBottom: "1px solid var(--line)", color: urgente ? "var(--danger)" : "var(--ink-2)", padding: "9px 16px", fontSize: 13, textAlign: "center", lineHeight: 1.4 }}>
            {giorni > 1
              ? `La tua versione di prova scade tra ${giorni} giorni (${fmtDate(auth.scadenza)}).`
              : giorni === 1
                ? `La tua versione di prova scade domani (${fmtDate(auth.scadenza)}).`
                : "La tua versione di prova scade oggi."}{" "}
            Per continuare a usarla, contatta il rivenditore.
          </div>
        );
      })()}

      {menuOpen && (
        <>
          <div className="drawer-overlay" onClick={() => setMenuOpen(false)} />
          <aside className="drawer" role="navigation" aria-label="Menu principale">
            <div className="drawer-head">
              <div className="brand-mark"><img src={ICON_INTERVENTIA} alt="interventia" /></div>
              <div className="brand-name">interventia</div>
            </div>
            {[
              ["rapportini", "Rapportini", <IcoDoc key="d" />],
              ["agenda", "Agenda", <svg key="cal" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="4" width="18" height="17" rx="2" /><path d="M3 9h18M8 3v3M16 3v3" /></svg>],
              ["assistenza", "Assistenza", <IcoBell key="b" />],
              ["clienti", "Clienti", <IcoUser key="u" />],
              ["fatture", "Fatture", <IcoReceipt key="r" />],
              ["materiale", "Materiale MABA", <svg key="pkg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M21 16V8l-9-5-9 5v8l9 5 9-5z" /><path d="M3.3 7 12 12l8.7-5M12 12v9" /></svg>],
            ].map(([k, lab, ico]) => (
              <button
                key={k}
                className={"drawer-item" + (tab === k ? " active" : "")}
                onClick={() => { setTab(k); setDetailCliId(null); setMenuOpen(false); }}
              >
                <span className="di-ic">{ico}</span>
                <span style={{ flex: 1 }}>{lab}</span>
                {k === "assistenza" && richieste.some((r) => r.stato !== "svolto") && <span className="tab-dot" style={{ margin: 0 }} />}
              </button>
            ))}
            <div style={{ marginTop: "auto", paddingTop: 10, borderTop: "1px solid var(--line)" }}>
              <button className="drawer-item" onClick={() => { setAziendaForm(azienda || emptyAzienda()); setMenuOpen(false); }}>
                <span className="di-ic"><IcoGear /></span>
                <span style={{ flex: 1 }}>Dati azienda</span>
              </button>
              <button className="drawer-item" onClick={() => { setAssistOpen(true); setMenuOpen(false); }}>
                <span className="di-ic"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M5 13v-1a7 7 0 0 1 14 0v1" /><path d="M5 13a2 2 0 0 0-2 2v0a2 2 0 0 0 2 2h1v-4H5zM19 13a2 2 0 0 1 2 2v0a2 2 0 0 1-2 2h-1v-4h1z" /><path d="M19 17v1a3 3 0 0 1-3 3h-2" /></svg></span>
                <span style={{ flex: 1 }}>Richiedi assistenza</span>
              </button>
              {auth.role === "reseller" && (
                <button className="drawer-item" onClick={() => { setLicenzeOpen(true); setMenuOpen(false); }}>
                  <span className="di-ic"><IcoKey /></span>
                  <span style={{ flex: 1 }}>Gestione licenze</span>
                </button>
              )}
              <button className="drawer-item" onClick={logout}>
                <span className="di-ic"><IcoLogout /></span>
                <span style={{ flex: 1 }}>Esci</span>
                <span style={{ fontSize: 11, color: "var(--muted)" }}>{auth.label}</span>
              </button>
            </div>
          </aside>
        </>
      )}

      <main className="container">
        {greet && (
          <div className="banner">
            <span>{greet} 👋</span>
            <button onClick={() => setGreet(null)} aria-label="Chiudi">×</button>
          </div>
        )}
        {tab === "rapportini" && (
          <RapportiniView
            rapportini={rapportini}
            cliById={cliById}
            onNew={openNuovoRapp}
            onOpen={openEditRapp}
            search={search}
            setSearch={setSearch}
          />
        )}

        {tab === "agenda" && (
          <AgendaView
            appuntamenti={appuntamenti}
            cliById={cliById}
            onNew={() => openNuovoApp()}
            onOpen={openEditApp}
            onToggle={toggleApp}
          />
        )}

        {tab === "assistenza" && (
          <AssistenzaView
            richieste={richieste}
            cliById={cliById}
            onNew={openNuovaRich}
            onOpen={openEditRich}
            onToggle={toggleRich}
            onPlan={pianificaDaRichiesta}
          />
        )}

        {tab === "clienti" && !detailCliId && (
          <ClientiView
            clienti={clienti}
            rapportini={rapportini}
            onNew={() => setCliForm(emptyCliente())}
            onOpen={(id) => setDetailCliId(id)}
            search={search}
            setSearch={setSearch}
          />
        )}

        {tab === "clienti" && detailCliId && cliById[detailCliId] && (
          <ClienteDetail
            cliente={cliById[detailCliId]}
            rapportini={rapportini.filter((r) => r.clienteId === detailCliId)}
            richieste={richieste.filter((r) => r.clienteId === detailCliId)}
            onBack={() => setDetailCliId(null)}
            onEditCliente={() => setCliForm(cliById[detailCliId])}
            onDeleteCliente={() => deleteCli(detailCliId)}
            onOpenRapp={openEditRapp}
            onNewRapp={() => {
              openNuovoRapp();
              setRappForm((f) => ({ ...f, cliMode: "existing", clienteId: detailCliId }));
            }}
            onMarkFatturati={(ids) =>
              persistRapp(rapportini.map((r) => (ids.includes(r.id) ? { ...r, fatturato: true } : r)))
            }
            onOpenRich={openEditRich}
            onToggleRich={toggleRich}
            onNewRich={() => {
              openNuovaRich();
              setRichForm((f) => ({ ...f, cliMode: "existing", clienteId: detailCliId }));
            }}
            azienda={azienda}
            onGenerateXml={generaXml}
          />
        )}
        {tab === "fatture" && (
          <FattureView
            fatture={fatture}
            onPreview={(f) => setPreviewFattura(f)}
            onDownload={(f) => download(f.filename, f.xml, "application/xml")}
          />
        )}

        {tab === "materiale" && (
          <MaterialeView
            azienda={azienda}
            ordini={ordiniMateriale}
            onSave={salvaOrdineMateriale}
          />
        )}
      </main>

      {rappForm && (
        <RapportinoForm
          form={rappForm}
          setForm={setRappForm}
          clienti={clienti}
          azienda={azienda}
          onSave={saveRapp}
          onClose={() => setRappForm(null)}
          onDelete={rappForm.id ? () => deleteRapp(rappForm.id) : null}
        />
      )}

      {cliForm && (
        <ClienteForm
          form={cliForm}
          setForm={setCliForm}
          onSave={saveCli}
          onClose={() => setCliForm(null)}
          onDelete={cliForm.id ? () => deleteCli(cliForm.id) : null}
        />
      )}

      {richForm && (
        <RichiestaForm
          form={richForm}
          setForm={setRichForm}
          clienti={clienti}
          onSave={saveRich}
          onClose={() => setRichForm(null)}
          onDelete={richForm.id ? () => deleteRich(richForm.id) : null}
        />
      )}

      {appForm && (
        <AppuntamentoForm
          form={appForm}
          setForm={setAppForm}
          clienti={clienti}
          onSave={saveApp}
          onClose={() => setAppForm(null)}
          onDelete={appForm.id ? () => deleteApp(appForm.id) : null}
        />
      )}

      {assistOpen && <RichiediAssistenzaModal onClose={() => setAssistOpen(false)} />}

      {aziendaForm && (
        <AziendaForm
          form={aziendaForm}
          setForm={setAziendaForm}
          onSave={saveAzienda}
          onClose={() => setAziendaForm(null)}
        />
      )}

      {previewFattura && (
        <FatturaPreview
          fattura={previewFattura}
          logo={azienda && azienda.logo}
          onClose={() => setPreviewFattura(null)}
          onDownload={() => download(previewFattura.filename, previewFattura.xml, "application/xml")}
          onDelete={() => {
            if (confirm("Eliminare questa fattura dall'elenco? L'XML non sarà più riscaricabile da qui.")) {
              deleteFattura(previewFattura.id);
              setPreviewFattura(null);
            }
          }}
        />
      )}

      {licenzeOpen && auth.role === "reseller" && (
        <LicenzeManager
          licenze={licenze}
          onCreate={createLicenza}
          onDelete={deleteLicenza}
          onClose={() => setLicenzeOpen(false)}
        />
      )}
    </div>
  );
}

/* ============================================================
   VISTA RAPPORTINI
   ============================================================ */

function RapportiniView({ rapportini, cliById, onNew, onOpen, search, setSearch }) {
  const [filtro, setFiltro] = useState("tutti"); // tutti | dafatturare | fatturati
  const list = useMemo(() => {
    let l = [...rapportini].sort((a, b) => (b.data || "").localeCompare(a.data || "") || (b.createdAt || 0) - (a.createdAt || 0));
    if (filtro === "dafatturare") l = l.filter((r) => !r.fatturato);
    if (filtro === "fatturati") l = l.filter((r) => r.fatturato);
    const s = search.trim().toLowerCase();
    if (s)
      l = l.filter(
        (r) =>
          nomeCliente(cliById[r.clienteId]).toLowerCase().includes(s) ||
          (r.descrizione || "").toLowerCase().includes(s) ||
          (r.luogo || "").toLowerCase().includes(s)
      );
    return l;
  }, [rapportini, filtro, search, cliById]);

  return (
    <>
      <div className="page-head">
        <h1>Rapportini<span className="count">{rapportini.length}</span></h1>
        <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
          <input className="search" placeholder="Cerca…" value={search} onChange={(e) => setSearch(e.target.value)} />
          <div style={{ display: "flex", gap: 2, background: "var(--surface)", border: "1px solid var(--line)", borderRadius: 10, padding: 2 }}>
            {[["tutti", "Tutti"], ["dafatturare", "Da fatturare"], ["fatturati", "Fatturati"]].map(([k, lab]) => (
              <button key={k} className={"tab btn-sm" + (filtro === k ? " active" : "")} style={{ borderRadius: 8 }} onClick={() => setFiltro(k)}>{lab}</button>
            ))}
          </div>
        </div>
      </div>

      {list.length === 0 ? (
        <div className="card empty">
          <div className="e-ic"><Wrench c="currentColor" s={24} /></div>
          <h3>{rapportini.length ? "Nessun rapportino con questi filtri" : "Ancora nessun rapportino"}</h3>
          <p>{rapportini.length ? "Prova a cambiare filtro o ricerca." : "Crea il primo rapportino dopo un intervento."}</p>
          {!rapportini.length && <button className="btn btn-primary" onClick={onNew}>＋ Nuovo rapportino</button>}
        </div>
      ) : (
        <div className="stack">
          {list.map((r) => {
            const cli = cliById[r.clienteId];
            const nArt = (r.articoli || []).length;
            const val = haValore(r);
            const meta = [
              (Number(r.ore) || 0) > 0 ? `${Number(r.ore).toLocaleString("it-IT")} h` : null,
              nArt ? `${nArt} articol${nArt === 1 ? "o" : "i"}` : null,
              r.luogo || r.descrizione || null,
            ].filter(Boolean).join(" · ");
            const d = new Date(r.data);
            return (
              <button key={r.id} className="rapp" onClick={() => onOpen(r)}>
                <div className="when">
                  <div className="d num">{isNaN(d) ? "—" : d.toLocaleDateString("it-IT", { day: "2-digit", month: "short" })}</div>
                  <div className="n num">N. {r.numero}</div>
                </div>
                <div className="body">
                  <div className="cli">{cli ? nomeCliente(cli) : "Cliente eliminato"}</div>
                  <div className="meta">{meta || "—"}</div>
                </div>
                <div className="right">
                  {val ? <div className="imp num copper">{fmtMoney(importoRapp(r))}</div> : <div className="imp num" style={{ color: "var(--muted)" }}>—</div>}
                  <span className={"badge " + (r.fatturato ? "ok" : "warn")}><span className="dot" />{r.fatturato ? "Fatturato" : "Da fatturare"}</span>
                </div>
              </button>
            );
          })}
        </div>
      )}
    </>
  );
}

/* ============================================================
   VISTA CLIENTI
   ============================================================ */

function ClientiView({ clienti, rapportini, onNew, onOpen, search, setSearch }) {
  const counts = useMemo(() => {
    const m = {};
    rapportini.forEach((r) => {
      m[r.clienteId] = m[r.clienteId] || { tot: 0, daf: 0 };
      m[r.clienteId].tot++;
      if (!r.fatturato) m[r.clienteId].daf++;
    });
    return m;
  }, [rapportini]);

  const list = useMemo(() => {
    const s = search.trim().toLowerCase();
    return [...clienti]
      .filter((c) => !s || nomeCliente(c).toLowerCase().includes(s) || (c.piva || "").includes(s) || (c.cf || "").toLowerCase().includes(s))
      .sort((a, b) => nomeCliente(a).localeCompare(nomeCliente(b)));
  }, [clienti, search]);

  return (
    <>
      <div className="page-head">
        <h1>Clienti<span className="count">{clienti.length}</span></h1>
        <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
          <input className="search" placeholder="Cerca cliente…" value={search} onChange={(e) => setSearch(e.target.value)} />
          <button className="btn btn-accent" onClick={onNew}>＋ Nuovo cliente</button>
        </div>
      </div>

      {list.length === 0 ? (
        <div className="card empty">
          <div className="e-ic" style={{ fontSize: 24 }}>👤</div>
          <h3>{clienti.length ? "Nessun cliente trovato" : "Ancora nessun cliente"}</h3>
          <p>{clienti.length ? "Prova un'altra ricerca." : "Aggiungi un cliente, oppure creane uno al volo dentro un rapportino."}</p>
          {!clienti.length && <button className="btn btn-primary" onClick={onNew}>＋ Nuovo cliente</button>}
        </div>
      ) : (
        <div className="stack">
          {list.map((c) => {
            const ct = counts[c.id] || { tot: 0, daf: 0 };
            const det = [c.piva ? "P.IVA " + c.piva : c.cf ? "C.F. " + c.cf : null, c.telefono].filter(Boolean).join(" · ");
            return (
              <button key={c.id} className="cli-row" onClick={() => onOpen(c.id)}>
                <div className="avatar">{(nomeCliente(c) || "?").trim().charAt(0).toUpperCase()}</div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div className="nm">{nomeCliente(c)}</div>
                  <div className="det">{det || "—"}</div>
                </div>
                <div style={{ textAlign: "right", display: "flex", flexDirection: "column", gap: 5, alignItems: "flex-end" }}>
                  <span style={{ fontSize: 13, color: "var(--muted)", fontWeight: 600 }} className="num">{ct.tot} rapportin{ct.tot === 1 ? "o" : "i"}</span>
                  {ct.daf > 0 && <span className="badge warn"><span className="dot" />{ct.daf} da fatturare</span>}
                </div>
              </button>
            );
          })}
        </div>
      )}
    </>
  );
}

/* ============================================================
   DETTAGLIO CLIENTE
   ============================================================ */

function ClienteDetail({ cliente, rapportini, richieste = [], onBack, onEditCliente, onDeleteCliente, onOpenRapp, onNewRapp, onMarkFatturati, onOpenRich, onToggleRich, onNewRich, azienda, onGenerateXml }) {
  const sorted = useMemo(
    () => [...rapportini].sort((a, b) => (b.data || "").localeCompare(a.data || "")),
    [rapportini]
  );
  const [sel, setSel] = useState(() => sorted.filter((r) => !r.fatturato).map((r) => r.id));
  const [xmlMsg, setXmlMsg] = useState(null);
  const [xmlDlg, setXmlDlg] = useState(false);
  const [metodoPag, setMetodoPag] = useState((azienda && azienda.modalitaPagamento) || "MP05");

  const toggle = (id) => setSel((s) => (s.includes(id) ? s.filter((x) => x !== id) : [...s, id]));
  const selRapp = sorted.filter((r) => sel.includes(r.id));
  const totOre = selRapp.reduce((s, r) => s + (Number(r.ore) || 0), 0);
  const totImp = selRapp.reduce((s, r) => s + importoRapp(r), 0);
  const valorizzato = selRapp.some(haValore);

  const billItems = [
    ["Indirizzo", indirizzoCliente(cliente)],
    ["Codice fiscale", cliente.cf],
    ["Partita IVA", cliente.piva],
    ["Codice SDI", cliente.sdi],
    ["PEC", cliente.pec],
    ["Email", cliente.email],
    ["Telefono", cliente.telefono],
  ].filter(([, v]) => v);

  const esporta = (tipo) => {
    if (!selRapp.length) return;
    const base = `riepilogo-${slug(nomeCliente(cliente))}-${todayISO()}`;
    if (tipo === "html") download(base + ".html", buildHtmlReport(cliente, selRapp), "text/html");
    else download(base + ".csv", buildCsv(cliente, selRapp), "text/csv");
  };

  return (
    <>
      <button className="back" onClick={onBack}>‹ Tutti i clienti</button>

      <div className="card detail-card">
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12, flexWrap: "wrap" }}>
          <div style={{ display: "flex", gap: 14, alignItems: "center" }}>
            <div className="avatar" style={{ width: 48, height: 48, fontSize: 18 }}>{(nomeCliente(cliente) || "?").charAt(0).toUpperCase()}</div>
            <div>
              <h1 style={{ margin: 0, fontSize: 22 }}>{nomeCliente(cliente)}</h1>
              <div style={{ color: "var(--muted)", fontSize: 14 }}>{rapportini.length} rapportin{rapportini.length === 1 ? "o" : "i"} totali</div>
            </div>
          </div>
          <div style={{ display: "flex", gap: 6 }}>
            <button className="btn btn-sm" onClick={onEditCliente}>Modifica dati</button>
            <button className="btn btn-danger btn-sm" onClick={onDeleteCliente}>Elimina</button>
          </div>
        </div>
        {billItems.length > 0 ? (
          <div className="billing">
            {billItems.map(([k, v]) => (
              <div key={k}><div className="k">{k}</div><div className="v">{v}</div></div>
            ))}
          </div>
        ) : (
          <div className="help" style={{ marginTop: 12 }}>Solo il nome è registrato. Aggiungi indirizzo e P.IVA/C.F. con “Modifica dati” per la fatturazione.</div>
        )}
      </div>

      {(richieste.length > 0 || onNewRich) && (
        <>
          <div className="page-head" style={{ marginBottom: 14 }}>
            <h2 style={{ fontSize: 18, margin: 0 }}>
              Richieste di assistenza
              {richieste.some((r) => r.stato !== "svolto") && (
                <span className="count" style={{ color: "var(--amber)" }}>
                  {richieste.filter((r) => r.stato !== "svolto").length} da gestire
                </span>
              )}
            </h2>
            {onNewRich && <button className="btn btn-sm" onClick={onNewRich}>＋ Nuova richiesta</button>}
          </div>
          {richieste.length === 0 ? (
            <div className="help" style={{ marginBottom: 22 }}>Nessuna richiesta per questo cliente.</div>
          ) : (
            <div className="stack" style={{ marginBottom: 22 }}>
              {[...richieste]
                .sort((a, b) => (a.stato === b.stato ? (b.createdAt || 0) - (a.createdAt || 0) : a.stato === "svolto" ? 1 : -1))
                .map((r) => (
                  <div key={r.id} className="rapp" style={{ cursor: "default" }}>
                    <div className="when" style={{ width: 60 }}>
                      <div className="d num">{fmtDate(r.data).slice(0, 5)}</div>
                    </div>
                    <button className="body" style={{ border: "none", background: "none", textAlign: "left", padding: 0 }} onClick={() => onOpenRich && onOpenRich(r)}>
                      <div style={{ fontWeight: 500, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{r.descrizione}</div>
                    </button>
                    <button
                      className={"badge clickable " + (r.stato === "svolto" ? "ok" : "warn")}
                      onClick={() => onToggleRich && onToggleRich(r.id)}
                      title="Cambia stato"
                    >
                      <span className="dot" />{r.stato === "svolto" ? "Svolto" : "Da gestire"}
                    </button>
                  </div>
                ))}
            </div>
          )}
        </>
      )}

      <div className="page-head" style={{ marginBottom: 14 }}>
        <h2 style={{ fontSize: 18, margin: 0 }}>Rapportini</h2>
        <button className="btn btn-sm" onClick={onNewRapp}>＋ Aggiungi per questo cliente</button>
      </div>

      {xmlMsg && (
        <div className="banner">
          <span>{xmlMsg}</span>
          <button onClick={() => setXmlMsg(null)} aria-label="Chiudi">×</button>
        </div>
      )}

      {sorted.length > 0 && (
        <div className="toolbar">
          <span className="info">
            {sel.length} selezionat{sel.length === 1 ? "o" : "i"} · {totOre.toLocaleString("it-IT")} h{valorizzato ? " · " + fmtMoney(totImp) : ""}
          </span>
          <button className="btn btn-sm" onClick={() => setSel(sorted.map((r) => r.id))}>Seleziona tutti</button>
          <button className="btn btn-sm" onClick={() => setSel([])}>Deseleziona</button>
        </div>
      )}

      {sorted.length === 0 ? (
        <div className="card empty">
          <div className="e-ic"><Wrench c="currentColor" s={24} /></div>
          <h3>Nessun rapportino per {nomeCliente(cliente)}</h3>
          <p>Appena fai un intervento, registralo qui.</p>
          <button className="btn btn-primary" onClick={onNewRapp}>＋ Aggiungi rapportino</button>
        </div>
      ) : (
        <div className="stack">
          {sorted.map((r) => {
            const nArt = (r.articoli || []).length;
            const val = haValore(r);
            const meta = [
              (Number(r.ore) || 0) > 0 ? `${Number(r.ore).toLocaleString("it-IT")} h` : null,
              nArt ? `${nArt} articol${nArt === 1 ? "o" : "i"}` : null,
              r.descrizione || r.luogo || null,
            ].filter(Boolean).join(" · ");
            return (
              <div key={r.id} className="rapp" style={{ cursor: "default" }}>
                <input type="checkbox" className="check" checked={sel.includes(r.id)} onChange={() => toggle(r.id)} />
                <div className="when" style={{ width: 70 }}>
                  <div className="d num">{fmtDate(r.data).slice(0, 5)}</div>
                  <div className="n num">N. {r.numero}</div>
                </div>
                <button className="body" style={{ border: "none", background: "none", textAlign: "left", padding: 0 }} onClick={() => onOpenRapp(r)}>
                  <div className="meta" style={{ color: "var(--ink)", fontWeight: 500, marginTop: 0 }}>{meta || "Rapportino"}</div>
                </button>
                <div className="right">
                  {val ? <div className="imp num copper">{fmtMoney(importoRapp(r))}</div> : <div className="imp num" style={{ color: "var(--muted)" }}>—</div>}
                  <span className={"badge " + (r.fatturato ? "ok" : "warn")}><span className="dot" />{r.fatturato ? "Fatturato" : "Da fatturare"}</span>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {sorted.length > 0 && (
        <div className="toolbar actions">
          <button className="btn btn-copper btn-sm" onClick={() => esporta("html")} disabled={!sel.length}>⤓ Genera riepilogo</button>
          <button className="btn btn-primary btn-sm" onClick={() => sel.length && setXmlDlg(true)} disabled={!sel.length}>⤓ Genera XML</button>
          <button className="btn btn-sm" disabled={!sel.length} onClick={() => onMarkFatturati(sel)}>Segna come fatturati</button>
        </div>
      )}

      {xmlDlg && (
        <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && setXmlDlg(false)}>
          <div className="modal" style={{ maxWidth: 420 }}>
            <div className="modal-head"><h2>Genera fattura XML</h2><button className="icon-x" onClick={() => setXmlDlg(false)}>×</button></div>
            <div className="modal-body">
              <div className="field">
                <span className="label">Metodo di pagamento</span>
                <select className="select" value={metodoPag} onChange={(e) => setMetodoPag(e.target.value)}>
                  {MODI_PAG.map(([k, lab]) => <option key={k} value={k}>{lab}</option>)}
                </select>
                <div className="help">Vale solo per questa fattura — il valore predefinito è in Dati azienda.</div>
              </div>
              <div className="help">{sel.length} rapportin{sel.length === 1 ? "o" : "i"} selezionat{sel.length === 1 ? "o" : "i"}.</div>
            </div>
            <div className="modal-foot">
              <button className="btn" onClick={() => setXmlDlg(false)}>Annulla</button>
              <button className="btn btn-primary" onClick={() => { const m = onGenerateXml(cliente, selRapp, { modalitaPagamento: metodoPag }); setXmlMsg(m); setXmlDlg(false); }}>Genera XML</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

/* ============================================================
   CAMPI NUOVO CLIENTE (riusati nei form rapportino/richiesta)
   ============================================================ */

function NuovoClienteFields({ nuovoCli, setCli, compact }) {
  return (
    <div className="card" style={{ padding: 16, marginBottom: 14, background: "var(--bg-tint)" }}>
      <div className="field">
        <span className="label">Tipo soggetto</span>
        <div style={{ display: "flex", gap: 8 }}>
          {[["persona", "Persona fisica"], ["azienda", "Azienda"]].map(([k, lab]) => (
            <button key={k} className={"btn" + (nuovoCli.tipo === k ? " btn-primary" : "")} style={{ flex: 1, justifyContent: "center" }} onClick={() => setCli("tipo", k)}>{lab}</button>
          ))}
        </div>
      </div>
      {nuovoCli.tipo === "azienda" ? (
        <div className="field"><span className="label">Denominazione *</span><input className="input" value={nuovoCli.denominazione} onChange={(e) => setCli("denominazione", e.target.value)} placeholder="es. Rossi Impianti S.r.l." autoFocus /></div>
      ) : (
        <div className="row2">
          <div className="field"><span className="label">Nome *</span><input className="input" value={nuovoCli.nome} onChange={(e) => setCli("nome", e.target.value)} placeholder="Mario" autoFocus /></div>
          <div className="field"><span className="label">Cognome</span><input className="input" value={nuovoCli.cognome} onChange={(e) => setCli("cognome", e.target.value)} placeholder="Rossi" /></div>
        </div>
      )}
      {compact ? (
        <div className="field"><span className="label">Telefono</span><input className="input" value={nuovoCli.telefono} onChange={(e) => setCli("telefono", e.target.value)} placeholder="Per richiamarlo" /></div>
      ) : (
        <>
          <div className="field"><span className="label">Indirizzo (via e civico)</span><input className="input" value={nuovoCli.indirizzo} onChange={(e) => setCli("indirizzo", e.target.value)} placeholder="es. Via Garibaldi 12" /></div>
          <div className="row3">
            <div className="field"><span className="label">CAP</span><input className="input" value={nuovoCli.cap} onChange={(e) => setCli("cap", e.target.value)} /></div>
            <div className="field"><span className="label">Comune</span><input className="input" value={nuovoCli.comune} onChange={(e) => setCli("comune", e.target.value)} /></div>
            <div className="field"><span className="label">Prov.</span><input className="input" value={nuovoCli.provincia} onChange={(e) => setCli("provincia", e.target.value)} maxLength={2} /></div>
          </div>
          <div className="row2">
            <div className="field"><span className="label">Codice fiscale</span><input className="input" value={nuovoCli.cf} onChange={(e) => setCli("cf", e.target.value)} /></div>
            <div className="field"><span className="label">Partita IVA</span><input className="input" value={nuovoCli.piva} onChange={(e) => setCli("piva", e.target.value)} /></div>
          </div>
        </>
      )}
      <div className="help">{compact ? "Bastano questi dati: il resto si completa dalla scheda cliente." : "Indirizzo e dati fiscali servono per la fattura — puoi completarli anche più avanti."}</div>
    </div>
  );
}

/* ============================================================
   FORM RAPPORTINO
   ============================================================ */

function RapportinoForm({ form, setForm, clienti, azienda, onSave, onClose, onDelete }) {
  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));
  const setCli = (k, v) => setForm((f) => ({ ...f, nuovoCli: { ...f.nuovoCli, [k]: v } }));

  const forfettario = azienda?.regimeFiscale === "RF19";
  const aliquotaDefault = Number(azienda?.aliquotaIva) || 22;
  const aliquoteOpts = forfettario ? [] : Array.from(new Set([...(azienda?.aliquoteIva || [22, 10, 4]).map(Number), aliquotaDefault])).filter((x) => !isNaN(x)).sort((a, b) => b - a);

  const [showTariffa, setShowTariffa] = useState((form.tariffaOraria || 0) > 0);
  const addArt = () => set("articoli", [...(form.articoli || []), { id: uid(), descrizione: "", prezzo: "", aliquota: forfettario ? null : aliquotaDefault }]);
  const setArt = (i, k, v) => set("articoli", form.articoli.map((a, idx) => (idx === i ? { ...a, [k]: v } : a)));
  const delArt = (i) => set("articoli", form.articoli.filter((_, idx) => idx !== i));

  const canSave =
    form.cliMode === "existing" ? !!form.clienteId : !!nomeCliente(form.nuovoCli).trim();

  const previewImp =
    (numOrNull(form.ore) || 0) * (numOrNull(form.tariffaOraria) || 0) +
    (form.articoli || []).reduce((s, a) => s + (numOrNull(a.prezzo) || 0), 0);

  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal">
        <div className="modal-head">
          <h2>{form.id ? "Modifica rapportino" : "Nuovo rapportino"} <span style={{ color: "var(--muted)", fontWeight: 500, fontSize: 14 }}>N. {form.numero}</span></h2>
          <button className="icon-x" onClick={onClose}>×</button>
        </div>

        <div className="modal-body">
          {/* cliente */}
          <div className="field">
            <span className="label">Cliente</span>
            {clienti.length > 0 && (
              <select
                className="select"
                value={form.cliMode === "new" ? "__new__" : form.clienteId}
                onChange={(e) => {
                  if (e.target.value === "__new__") set("cliMode", "new");
                  else setForm((f) => ({ ...f, cliMode: "existing", clienteId: e.target.value }));
                }}
              >
                {form.cliMode === "existing" && !form.clienteId && <option value="">Seleziona un cliente…</option>}
                {clienti.map((c) => <option key={c.id} value={c.id}>{nomeCliente(c)}</option>)}
                <option value="__new__">＋ Nuovo cliente…</option>
              </select>
            )}
          </div>

          {(form.cliMode === "new" || clienti.length === 0) && (
            <NuovoClienteFields nuovoCli={form.nuovoCli} setCli={setCli} />
          )}

          <div className="row2">
            <div className="field"><span className="label">Data</span><input type="date" className="input" value={form.data} onChange={(e) => set("data", e.target.value)} /></div>
            <div className="field"><span className="label">Luogo intervento</span><input className="input" value={form.luogo} onChange={(e) => set("luogo", e.target.value)} placeholder="es. appartamento, cantiere…" /></div>
          </div>

          <div className="field">
            <span className="label">Descrizione del lavoro</span>
            <textarea className="textarea" value={form.descrizione} onChange={(e) => set("descrizione", e.target.value)} placeholder="Cosa è stato fatto…" />
          </div>

          {/* ore + tariffa */}
          <div className="row2">
            <div className="field">
              <span className="label">Ore lavorate</span>
              <input type="number" min="0" step="0.5" inputMode="decimal" className="input" value={form.ore} onChange={(e) => set("ore", e.target.value)} placeholder="0" />
            </div>
            <div className="field">
              <span className="label" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                Tariffa oraria
                {!showTariffa && <button className="btn-ghost btn-sm" style={{ padding: "2px 6px", fontSize: 12, color: "var(--petrol)" }} onClick={() => setShowTariffa(true)}>+ aggiungi</button>}
              </span>
              {showTariffa ? (
                <div style={{ position: "relative" }}>
                  <input type="number" min="0" step="1" inputMode="decimal" className="input" style={{ paddingLeft: 26 }} value={form.tariffaOraria} onChange={(e) => set("tariffaOraria", e.target.value)} placeholder="0" />
                  <span style={{ position: "absolute", left: 11, top: 10, color: "var(--muted)" }}>€</span>
                </div>
              ) : (
                <div className="help" style={{ paddingTop: 10 }}>Opzionale — lascia all'amministrazione.</div>
              )}
            </div>
          </div>

          {/* articoli */}
          <div className="field">
            <span className="label">Articoli e materiali</span>
            {(form.articoli || []).map((a, i) => (
              <div className={"art-row" + (forfettario ? "" : " iva")} key={a.id || i}>
                <input className="input" value={a.descrizione} onChange={(e) => setArt(i, "descrizione", e.target.value)} placeholder="Descrizione articolo" />
                <div style={{ position: "relative" }}>
                  <input type="number" min="0" step="0.01" inputMode="decimal" className="input" style={{ paddingLeft: 22 }} value={a.prezzo} onChange={(e) => setArt(i, "prezzo", e.target.value)} placeholder="—" />
                  <span style={{ position: "absolute", left: 9, top: 10, color: "var(--muted)", fontSize: 14 }}>€</span>
                </div>
                {!forfettario && (
                  <select className="select" style={{ padding: "10px 6px" }} value={a.aliquota ?? aliquotaDefault} onChange={(e) => setArt(i, "aliquota", e.target.value)} title="Aliquota IVA">
                    {aliquoteOpts.map((al) => <option key={al} value={al}>{al}%</option>)}
                  </select>
                )}
                <button className="x" onClick={() => delArt(i)} title="Rimuovi">×</button>
              </div>
            ))}
            <button className="btn btn-sm" style={{ marginTop: 2 }} onClick={addArt}>＋ Aggiungi articolo</button>
            <div className="help" style={{ marginTop: 6 }}>Il prezzo è facoltativo.</div>
          </div>

          <div className="field">
            <span className="label">Note</span>
            <textarea className="textarea" style={{ minHeight: 48 }} value={form.note} onChange={(e) => set("note", e.target.value)} placeholder="Note interne (non in fattura)…" />
          </div>

          <label style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer", fontSize: 14, fontWeight: 600 }}>
            <input type="checkbox" className="check" checked={form.fatturato} onChange={(e) => set("fatturato", e.target.checked)} />
            Già inviato/fatturato
          </label>

          {previewImp > 0 && (
            <div style={{ marginTop: 16, padding: "12px 14px", background: "var(--copper-soft)", borderRadius: 10, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ fontWeight: 600, color: "var(--copper)" }}>Importo indicativo</span>
              <span className="num" style={{ fontWeight: 700, fontSize: 17, color: "var(--copper)" }}>{fmtMoney(previewImp)}</span>
            </div>
          )}
        </div>

        <div className="modal-foot">
          {onDelete && <button className="btn btn-danger" style={{ marginRight: "auto" }} onClick={onDelete}>Elimina</button>}
          <button className="btn" onClick={onClose}>Annulla</button>
          <button className="btn btn-primary" disabled={!canSave} onClick={onSave}>Salva rapportino</button>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   FORM CLIENTE
   ============================================================ */

function ClienteForm({ form, setForm, onSave, onClose, onDelete }) {
  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));
  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal">
        <div className="modal-head">
          <h2>{form.id ? "Modifica cliente" : "Nuovo cliente"}</h2>
          <button className="icon-x" onClick={onClose}>×</button>
        </div>
        <div className="modal-body">
          <div className="field">
            <span className="label">Tipo soggetto</span>
            <div style={{ display: "flex", gap: 8 }}>
              {[["persona", "Persona fisica"], ["azienda", "Azienda"]].map(([k, lab]) => (
                <button key={k} className={"btn" + (form.tipo === k ? " btn-primary" : "")} style={{ flex: 1, justifyContent: "center" }} onClick={() => set("tipo", k)}>{lab}</button>
              ))}
            </div>
          </div>

          {form.tipo === "azienda" ? (
            <div className="field">
              <span className="label">Denominazione / Ragione sociale *</span>
              <input className="input" value={form.denominazione} onChange={(e) => set("denominazione", e.target.value)} placeholder="es. Rossi Impianti S.r.l." autoFocus />
            </div>
          ) : (
            <div className="row2">
              <div className="field"><span className="label">Nome *</span><input className="input" value={form.nome} onChange={(e) => set("nome", e.target.value)} placeholder="Mario" autoFocus /></div>
              <div className="field"><span className="label">Cognome</span><input className="input" value={form.cognome} onChange={(e) => set("cognome", e.target.value)} placeholder="Rossi" /></div>
            </div>
          )}

          <div className="field">
            <span className="label">Indirizzo (via e civico)</span>
            <input className="input" value={form.indirizzo} onChange={(e) => set("indirizzo", e.target.value)} placeholder="es. Via Garibaldi 12" />
          </div>
          <div className="row3">
            <div className="field"><span className="label">CAP</span><input className="input" value={form.cap} onChange={(e) => set("cap", e.target.value)} placeholder="20121" /></div>
            <div className="field"><span className="label">Comune</span><input className="input" value={form.comune} onChange={(e) => set("comune", e.target.value)} placeholder="Milano" /></div>
            <div className="field"><span className="label">Prov.</span><input className="input" value={form.provincia} onChange={(e) => set("provincia", e.target.value)} placeholder="MI" maxLength={2} /></div>
          </div>

          <div className="row2">
            <div className="field"><span className="label">Codice fiscale</span><input className="input" value={form.cf} onChange={(e) => set("cf", e.target.value)} /></div>
            <div className="field"><span className="label">Partita IVA</span><input className="input" value={form.piva} onChange={(e) => set("piva", e.target.value)} /></div>
          </div>
          <div className="row2">
            <div className="field"><span className="label">Codice SDI</span><input className="input" value={form.sdi} onChange={(e) => set("sdi", e.target.value)} placeholder="Per fattura elettronica" /></div>
            <div className="field"><span className="label">PEC</span><input className="input" value={form.pec} onChange={(e) => set("pec", e.target.value)} /></div>
          </div>
          <div className="row2">
            <div className="field"><span className="label">Email</span><input className="input" value={form.email} onChange={(e) => set("email", e.target.value)} /></div>
            <div className="field"><span className="label">Telefono</span><input className="input" value={form.telefono} onChange={(e) => set("telefono", e.target.value)} /></div>
          </div>
        </div>
        <div className="modal-foot">
          {onDelete && <button className="btn btn-danger" style={{ marginRight: "auto" }} onClick={onDelete}>Elimina</button>}
          <button className="btn" onClick={onClose}>Annulla</button>
          <button className="btn btn-primary" disabled={!nomeCliente(form).trim()} onClick={onSave}>Salva cliente</button>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   VISTA ASSISTENZA (richieste dei clienti)
   ============================================================ */

function AssistenzaView({ richieste, cliById, onNew, onOpen, onToggle, onPlan }) {
  const [filtro, setFiltro] = useState("dagestire"); // dagestire | svolti | tutte
  const [search, setSearch] = useState("");

  const list = useMemo(() => {
    let l = [...richieste].sort((a, b) =>
      a.stato === b.stato ? (b.createdAt || 0) - (a.createdAt || 0) : a.stato === "svolto" ? 1 : -1
    );
    if (filtro === "dagestire") l = l.filter((r) => r.stato !== "svolto");
    if (filtro === "svolti") l = l.filter((r) => r.stato === "svolto");
    const s = search.trim().toLowerCase();
    if (s)
      l = l.filter(
        (r) =>
          nomeCliente(cliById[r.clienteId]).toLowerCase().includes(s) ||
          (r.descrizione || "").toLowerCase().includes(s)
      );
    return l;
  }, [richieste, filtro, search, cliById]);

  const daGestire = richieste.filter((r) => r.stato !== "svolto").length;

  return (
    <>
      <div className="page-head">
        <h1>
          Assistenza
          {daGestire > 0 && <span className="count" style={{ color: "var(--amber)" }}>{daGestire} da gestire</span>}
        </h1>
        <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
          <input className="search" placeholder="Cerca…" value={search} onChange={(e) => setSearch(e.target.value)} />
          <div style={{ display: "flex", gap: 2, background: "var(--surface)", border: "1px solid var(--line)", borderRadius: 10, padding: 2 }}>
            {[["dagestire", "Da gestire"], ["svolti", "Svolti"], ["tutte", "Tutte"]].map(([k, lab]) => (
              <button key={k} className={"tab btn-sm" + (filtro === k ? " active" : "")} style={{ borderRadius: 8 }} onClick={() => setFiltro(k)}>{lab}</button>
            ))}
          </div>
          <button className="btn btn-accent" onClick={onNew}>＋ Nuova richiesta</button>
        </div>
      </div>

      {list.length === 0 ? (
        <div className="card empty">
          <div className="e-ic" style={{ fontSize: 24 }}>🛠️</div>
          <h3>{richieste.length ? "Nessuna richiesta con questo filtro" : "Nessuna richiesta di assistenza"}</h3>
          <p>{richieste.length ? "Prova a cambiare filtro o ricerca." : "Registra qui le chiamate e le richieste dei clienti da evadere."}</p>
          {!richieste.length && <button className="btn btn-primary" onClick={onNew}>＋ Nuova richiesta</button>}
        </div>
      ) : (
        <div className="stack">
          {list.map((r) => {
            const cli = cliById[r.clienteId];
            return (
              <div key={r.id} className="rapp" style={{ cursor: "default", alignItems: "flex-start" }}>
                <div className="when" style={{ width: 60, paddingTop: 2 }}>
                  <div className="d num">{fmtDate(r.data).slice(0, 5)}</div>
                </div>
                <button className="body" style={{ border: "none", background: "none", textAlign: "left", padding: 0 }} onClick={() => onOpen(r)}>
                  <div className="cli">{cli ? nomeCliente(cli) : "Cliente eliminato"}</div>
                  <div style={{ color: "var(--muted)", fontSize: 13, marginTop: 3, display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{r.descrizione}</div>
                </button>
                <div className="right" style={{ flexDirection: "column", alignItems: "flex-end", gap: 6 }}>
                  <button
                    className={"badge clickable " + (r.stato === "svolto" ? "ok" : "warn")}
                    onClick={() => onToggle(r.id)}
                    title="Tocca per cambiare stato"
                  >
                    <span className="dot" />{r.stato === "svolto" ? "Svolto" : "Da gestire"}
                  </button>
                  {onPlan && (
                    <button className="btn btn-sm" onClick={() => onPlan(r)} title="Crea un appuntamento in agenda">📅 Pianifica</button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </>
  );
}

/* ============================================================
   FORM RICHIESTA DI ASSISTENZA
   ============================================================ */

function RichiestaForm({ form, setForm, clienti, onSave, onClose, onDelete }) {
  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));
  const setCli = (k, v) => setForm((f) => ({ ...f, nuovoCli: { ...f.nuovoCli, [k]: v } }));

  const canSave =
    (form.cliMode === "existing" ? !!form.clienteId : !!nomeCliente(form.nuovoCli).trim()) && !!(form.descrizione || "").trim();

  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal">
        <div className="modal-head">
          <h2>{form.id ? "Modifica richiesta" : "Nuova richiesta di assistenza"}</h2>
          <button className="icon-x" onClick={onClose}>×</button>
        </div>

        <div className="modal-body">
          {/* cliente */}
          <div className="field">
            <span className="label">Cliente</span>
            {clienti.length > 0 && (
              <select
                className="select"
                value={form.cliMode === "new" ? "__new__" : form.clienteId}
                onChange={(e) => {
                  if (e.target.value === "__new__") set("cliMode", "new");
                  else setForm((f) => ({ ...f, cliMode: "existing", clienteId: e.target.value }));
                }}
              >
                {form.cliMode === "existing" && !form.clienteId && <option value="">Seleziona un cliente…</option>}
                {clienti.map((c) => <option key={c.id} value={c.id}>{nomeCliente(c)}</option>)}
                <option value="__new__">＋ Nuovo cliente…</option>
              </select>
            )}
          </div>

          {(form.cliMode === "new" || clienti.length === 0) && (
            <NuovoClienteFields nuovoCli={form.nuovoCli} setCli={setCli} compact />
          )}

          <div className="field">
            <span className="label">Data richiesta</span>
            <input type="date" className="input" value={form.data} onChange={(e) => set("data", e.target.value)} />
          </div>

          <div className="field">
            <span className="label">Descrizione del problema *</span>
            <textarea className="textarea" style={{ minHeight: 110 }} value={form.descrizione} onChange={(e) => set("descrizione", e.target.value)} placeholder="Cosa ha segnalato il cliente…" autoFocus={clienti.length > 0 && form.cliMode === "existing"} />
          </div>

          <div className="field">
            <span className="label">Stato</span>
            <div style={{ display: "flex", gap: 8 }}>
              {[["da_gestire", "Da gestire"], ["svolto", "Svolto"]].map(([k, lab]) => (
                <button
                  key={k}
                  className={"btn" + (form.stato === k ? " btn-primary" : "")}
                  style={{ flex: 1, justifyContent: "center" }}
                  onClick={() => set("stato", k)}
                >
                  {lab}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="modal-foot">
          {onDelete && <button className="btn btn-danger" style={{ marginRight: "auto" }} onClick={onDelete}>Elimina</button>}
          <button className="btn" onClick={onClose}>Annulla</button>
          <button className="btn btn-primary" disabled={!canSave} onClick={onSave}>Salva richiesta</button>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   FORM DATI AZIENDA (cedente/prestatore per la fattura)
   ============================================================ */

function AziendaForm({ form, setForm, onSave, onClose }) {
  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));
  const forfettario = form.regimeFiscale === "RF19";
  const [aliqText, setAliqText] = useState((form.aliquoteIva || [22]).join(", "));

  const onLogoFile = (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!file || !file.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        const max = 320;
        let w = img.width, h = img.height;
        if (w > max || h > max) { const r = Math.min(max / w, max / h); w = Math.round(w * r); h = Math.round(h * r); }
        const canvas = document.createElement("canvas");
        canvas.width = w; canvas.height = h;
        canvas.getContext("2d").drawImage(img, 0, 0, w, h);
        try { set("logo", canvas.toDataURL("image/png")); } catch (err) { set("logo", reader.result); }
      };
      img.onerror = () => set("logo", reader.result);
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  };
  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal">
        <div className="modal-head">
          <h2>Dati azienda</h2>
          <button className="icon-x" onClick={onClose}>×</button>
        </div>
        <div className="modal-body">
          <div className="help" style={{ marginBottom: 14 }}>Sono i tuoi dati di cedente/prestatore: vengono inseriti nella fattura elettronica XML.</div>

          <div className="field">
            <span className="label">Logo (usato nelle fatture)</span>
            <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
              {form.logo ? (
                <img src={form.logo} alt="Logo" style={{ height: 48, maxWidth: 150, objectFit: "contain", border: "1px solid var(--line)", borderRadius: 8, background: "var(--surface)", padding: 4 }} />
              ) : (
                <div style={{ height: 48, width: 48, borderRadius: 8, border: "1px dashed var(--line)", display: "flex", alignItems: "center", justifyContent: "center", color: "var(--muted)", fontSize: 12 }}>logo</div>
              )}
              <label className="btn btn-sm" style={{ cursor: "pointer" }}>
                {form.logo ? "Cambia" : "Importa logo"}
                <input type="file" accept="image/*" style={{ display: "none" }} onChange={onLogoFile} />
              </label>
              {form.logo && <button className="btn btn-danger btn-sm" onClick={() => set("logo", "")}>Rimuovi</button>}
            </div>
            <div className="help">PNG o JPG. Compare sull'anteprima e sulla copia di cortesia PDF (la fattura XML per lo SdI non include immagini).</div>
          </div>

          <div className="field">
            <span className="label">Denominazione / Ditta *</span>
            <input className="input" value={form.denominazione} onChange={(e) => set("denominazione", e.target.value)} placeholder="es. Termoidraulica Conti di Marco Conti" autoFocus />
          </div>
          <div className="row2">
            <div className="field"><span className="label">Partita IVA *</span><input className="input" value={form.partitaIva} onChange={(e) => set("partitaIva", e.target.value)} placeholder="11 cifre" /></div>
            <div className="field"><span className="label">Codice fiscale</span><input className="input" value={form.codiceFiscale} onChange={(e) => set("codiceFiscale", e.target.value)} /></div>
          </div>
          <div className="row2">
            <div className="field">
              <span className="label">Regime fiscale</span>
              <select className="select" value={form.regimeFiscale} onChange={(e) => set("regimeFiscale", e.target.value)}>
                {REGIMI.map(([k, lab]) => <option key={k} value={k}>{k} — {lab}</option>)}
              </select>
            </div>
            <div className="field">
              <span className="label">Aliquota IVA predefinita %</span>
              {forfettario ? (
                <div className="help" style={{ paddingTop: 10 }}>Regime forfettario: fattura senza IVA (Natura N2.2).</div>
              ) : (
                <input type="number" min="0" step="1" className="input" value={form.aliquotaIva} onChange={(e) => set("aliquotaIva", e.target.value)} />
              )}
            </div>
          </div>

          {!forfettario && (
            <div className="field">
              <span className="label">Aliquote IVA selezionabili</span>
              <input className="input" value={aliqText} onChange={(e) => { setAliqText(e.target.value); set("aliquoteIva", e.target.value.split(",").map((x) => Number(x.trim())).filter((x) => !isNaN(x))); }} placeholder="es. 22, 10, 4" />
              <div className="help">Separate da virgola. Sono le aliquote scegliibili per i ricambi nei rapportini.</div>
            </div>
          )}

          <div className="row2">
            <div className="field">
              <span className="label">Costo manodopera €/ora (imponibile)</span>
              <input type="number" min="0" step="0.5" inputMode="decimal" className="input" value={form.costoManodopera} onChange={(e) => set("costoManodopera", e.target.value)} placeholder="es. 35" />
            </div>
            <div className="field">
              <span className="label">Aliquota IVA manodopera %</span>
              {forfettario ? (
                <div className="help" style={{ paddingTop: 10 }}>0% in regime forfettario.</div>
              ) : (
                <input type="number" min="0" step="1" className="input" value={form.aliquotaManodopera} onChange={(e) => set("aliquotaManodopera", e.target.value)} />
              )}
            </div>
          </div>
          <div className="help" style={{ marginBottom: 14 }}>Il costo orario precompila la tariffa nei nuovi rapportini (modificabile per ogni lavoro); l'aliquota si applica alle righe di manodopera in fattura.</div>

          <div className="field">
            <span className="label">Indirizzo (via e civico)</span>
            <input className="input" value={form.indirizzo} onChange={(e) => set("indirizzo", e.target.value)} placeholder="es. Via dei Mestieri 5" />
          </div>
          <div className="row3">
            <div className="field"><span className="label">CAP</span><input className="input" value={form.cap} onChange={(e) => set("cap", e.target.value)} placeholder="20128" /></div>
            <div className="field"><span className="label">Comune</span><input className="input" value={form.comune} onChange={(e) => set("comune", e.target.value)} placeholder="Milano" /></div>
            <div className="field"><span className="label">Prov.</span><input className="input" value={form.provincia} onChange={(e) => set("provincia", e.target.value)} placeholder="MI" maxLength={2} /></div>
          </div>

          <div className="field">
            <span className="label">Modalità di pagamento predefinita</span>
            <select className="select" value={form.modalitaPagamento} onChange={(e) => set("modalitaPagamento", e.target.value)}>
              {MODI_PAG.map(([k, lab]) => <option key={k} value={k}>{lab}</option>)}
            </select>
          </div>
          <div className="row2">
            <div className="field"><span className="label">N. prossima fattura</span><input type="number" min="1" step="1" className="input" value={form.numeroProssimo} onChange={(e) => set("numeroProssimo", e.target.value)} /></div>
            <div className="field"><span className="label">Sezionale</span><input className="input" value={form.sezionale} onChange={(e) => set("sezionale", e.target.value)} placeholder="es. A — facoltativo" /></div>
          </div>
          <div className="help" style={{ marginBottom: 14 }}>Col sezionale il numero della fattura diventa, ad esempio, “12/A”.</div>
          <div className="field">
            <span className="label">IBAN (facoltativo)</span>
            <input className="input" value={form.iban} onChange={(e) => set("iban", e.target.value)} placeholder="IT..." />
          </div>
          <div className="field">
            <span className="label">Numero WhatsApp MABA (per richiesta materiale)</span>
            <input className="input" value={form.mabaTelefono || ""} onChange={(e) => set("mabaTelefono", e.target.value)} placeholder="es. 39 333 1234567" />
            <div className="help" style={{ marginTop: 6 }}>È il numero a cui vengono inviati gli ordini di materiale dalla sezione “Richiedi materiale - MABA”. Inseriscilo con il prefisso internazionale (39 per l'Italia).</div>
          </div>
        </div>
        <div className="modal-foot">
          <button className="btn" onClick={onClose}>Annulla</button>
          <button className="btn btn-primary" disabled={!form.denominazione.trim() || !form.partitaIva.trim()} onClick={onSave}>Salva dati</button>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   VISTA FATTURE (XML generati e archiviati)
   ============================================================ */

function FattureView({ fatture, onPreview, onDownload }) {
  const [search, setSearch] = useState("");
  const list = useMemo(() => {
    const s = search.trim().toLowerCase();
    return [...fatture]
      .sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))
      .filter((f) => !s || (f.clienteNome || "").toLowerCase().includes(s) || String(f.numero).includes(s) || (f.filename || "").toLowerCase().includes(s));
  }, [fatture, search]);

  return (
    <>
      <div className="page-head">
        <h1>Fatture<span className="count">{fatture.length}</span></h1>
        <input className="search" placeholder="Cerca…" value={search} onChange={(e) => setSearch(e.target.value)} />
      </div>

      {list.length === 0 ? (
        <div className="card empty">
          <div className="e-ic"><IcoReceipt s={26} /></div>
          <h3>{fatture.length ? "Nessuna fattura trovata" : "Nessuna fattura generata"}</h3>
          <p>{fatture.length ? "Prova un'altra ricerca." : "Le fatture XML che generi dalla scheda cliente vengono archiviate qui, pronte da riscaricare o vedere in anteprima."}</p>
        </div>
      ) : (
        <div className="stack">
          {list.map((f) => (
            <div key={f.id} className="rapp" style={{ cursor: "default" }}>
              <div className="when" style={{ width: 78 }}>
                <div className="d num">{fmtDate(f.data).slice(0, 5)}</div>
                <div className="n num">N. {f.numero}</div>
              </div>
              <button className="body" style={{ border: "none", background: "none", textAlign: "left", padding: 0 }} onClick={() => onPreview(f)}>
                <div className="cli">{f.clienteNome}</div>
                <div className="meta">{f.filename}</div>
              </button>
              <div className="right">
                <div className="imp num copper">{fmtMoney(f.totale)}</div>
                <div style={{ display: "flex", gap: 6 }}>
                  <button className="btn btn-sm" onClick={() => onDownload(f)}>XML</button>
                  <button className="btn btn-sm" onClick={() => onPreview(f)}>Anteprima</button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </>
  );
}

/* ============================================================
   ANTEPRIMA FATTURA (rappresentazione leggibile)
   ============================================================ */

function FatturaPreview({ fattura, logo, onClose, onDownload, onDelete }) {
  const f = fattura;
  const az = f.azienda || {};
  const cl = f.cliente || {};
  const regime = (REGIMI.find(([k]) => k === f.regimeFiscale) || [, ""])[1];
  const sedeAz = [az.indirizzo, ([az.cap, az.comune].filter(Boolean).join(" ") + (az.provincia ? ` (${az.provincia})` : "")).trim()].filter((x) => x && x.trim()).join(", ");
  const riep = f.riepiloghi || [{ aliquota: f.aliquota || 0, imponibile: f.imponibile, imposta: f.imposta }];
  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal modal-wide">
        <div className="modal-head">
          <h2>Fattura n. {f.numero}</h2>
          <button className="icon-x" onClick={onClose}>×</button>
        </div>
        <div className="modal-body">
          <div className="inv">
            {logo && <div style={{ marginBottom: 16 }}><img src={logo} alt="" style={{ height: 54, maxWidth: 220, objectFit: "contain" }} /></div>}
            <div className="inv-cols">
              <div>
                <div className="inv-lbl">Cedente / Prestatore</div>
                <div className="inv-name">{az.denominazione || "—"}</div>
                {az.partitaIva && <div className="ln">P.IVA {az.partitaIva}</div>}
                {sedeAz && <div className="ln">{sedeAz}</div>}
                {regime && <div className="ln">Regime {f.regimeFiscale} — {regime}</div>}
              </div>
              <div>
                <div className="inv-lbl">Cliente</div>
                <div className="inv-name">{nomeCliente(cl)}</div>
                {indirizzoCliente(cl) && <div className="ln">{indirizzoCliente(cl)}</div>}
                {cl.piva && <div className="ln">P.IVA {cl.piva}</div>}
                {cl.cf && <div className="ln">C.F. {cl.cf}</div>}
              </div>
            </div>

            <div className="inv-meta">
              <span>Numero {f.numero}</span>
              <span>Data {fmtDate(f.data)}</span>
              <span>TD01 — Fattura</span>
              <span>Pagamento: {modalitaLabel(f.modalitaPagamento)}</span>
              <span>{f.filename}</span>
            </div>

            <table className="inv-table">
              <thead>
                <tr><th>Descrizione</th><th className="num">Qtà</th><th className="num">Prezzo</th><th className="num">IVA</th><th className="num">Importo</th></tr>
              </thead>
              <tbody>
                {f.righe.map((r, i) => (
                  <tr key={i}>
                    <td>{r.descrizione}</td>
                    <td className="num">{Number(r.qta).toLocaleString("it-IT")}</td>
                    <td className="num">{fmtMoney(r.pu)}</td>
                    <td className="num">{Number(r.aliquota ?? (f.aliquota || 0)).toLocaleString("it-IT")}%</td>
                    <td className="num">{fmtMoney(r.tot)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="inv-tot">
              {riep.map((g, i) => (
                <React.Fragment key={i}>
                  <div className="r"><span>Imponibile {Number(g.aliquota).toLocaleString("it-IT")}%</span><span>{fmtMoney(g.imponibile)}</span></div>
                  <div className="r"><span>IVA {Number(g.aliquota).toLocaleString("it-IT")}%</span><span>{fmtMoney(g.imposta)}</span></div>
                </React.Fragment>
              ))}
              {f.bollo > 0 && <div className="r"><span>Imposta di bollo</span><span>{fmtMoney(f.bollo)}</span></div>}
              <div className="r grand"><span>Totale documento</span><span>{fmtMoney(f.totale)}</span></div>
            </div>
          </div>
        </div>
        <div className="modal-foot">
          {onDelete && <button className="btn btn-danger" style={{ marginRight: "auto" }} onClick={onDelete}>Elimina</button>}
          <button className="btn" onClick={onClose}>Chiudi</button>
          <button className="btn" onClick={() => stampaDocumento(buildCortesiaHTML(f, logo))} title="Copia di cortesia in PDF da inviare al cliente">Copia di cortesia (PDF)</button>
          <button className="btn btn-primary" onClick={onDownload}>⤓ Scarica XML</button>
        </div>
      </div>
    </div>
  );
}

