function LoginScreen({ onSubmit, onRegister, onBack }) {
  const [mode, setMode] = useState("login"); // "login" | "register"
  const [denom, setDenom] = useState("");
  const [email, setEmail] = useState("");
  const [pwd, setPwd] = useState("");
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const submit = async () => {
    if (busy) return;
    setBusy(true); setErr("");
    const e = mode === "login" ? await onSubmit(email, pwd) : await onRegister(denom, email, pwd);
    if (e) setErr(e);
    setBusy(false);
  };
  const switchMode = (m) => { setMode(m); setErr(""); };
  return (
    <div className="app">
      <Style />
      <div className="login">
        <div className="mesh" aria-hidden="true" />
        {onBack && (
          <button className="back" style={{ position: "absolute", top: 18, left: 18, marginBottom: 0 }} onClick={onBack}>‹ Indietro</button>
        )}
        <div className="login-collab">
          <span>In collaborazione con</span>
          <img src={LOGO_MABA} alt="MABA store" />
        </div>
        <div className="login-card">
          <img className="login-logo" src={LOGO_INTERVENTIA} alt="interventia" />
          <div className="login-sub">Rapportini, assistenza e fatturazione</div>

          {mode === "register" && (
            <>
              <div className="login-note">
                Prova gratuita di <b>7 giorni</b>, con clienti e rapportini di esempio già pronti.
              </div>
              <input
                className="input"
                type="text"
                value={denom}
                onChange={(e) => { setDenom(e.target.value); setErr(""); }}
                onKeyDown={(e) => e.key === "Enter" && submit()}
                placeholder="Nome della tua attività"
                autoFocus
                style={{ marginBottom: 8 }}
              />
            </>
          )}
          <input
            className="input"
            type="email"
            value={email}
            onChange={(e) => { setEmail(e.target.value); setErr(""); }}
            onKeyDown={(e) => e.key === "Enter" && submit()}
            placeholder="Email"
            autoFocus={mode === "login"}
            style={{ marginBottom: 8 }}
          />
          <input
            className="input"
            type="password"
            value={pwd}
            onChange={(e) => { setPwd(e.target.value); setErr(""); }}
            onKeyDown={(e) => e.key === "Enter" && submit()}
            placeholder={mode === "register" ? "Scegli una password (min 8 caratteri)" : "Password"}
          />
          <div className="login-err">{err}</div>
          <button className="btn btn-primary" style={{ width: "100%", justifyContent: "center" }} onClick={submit} disabled={busy}>
            {busy ? (mode === "login" ? "Accesso…" : "Creazione…") : (mode === "login" ? "Accedi" : "Inizia la prova gratuita")}
          </button>

          <div style={{ textAlign: "center", marginTop: 14, fontSize: 13, color: "var(--muted)" }}>
            {mode === "login" ? (
              <span>Non hai un account?{" "}
                <span className="login-switch" onClick={() => switchMode("register")}>Prova gratis 7 giorni</span>
              </span>
            ) : (
              <span>Hai già un account?{" "}
                <span className="login-switch" onClick={() => switchMode("login")}>Accedi</span>
              </span>
            )}
          </div>
        </div>
        <div className="login-foot">
          <span>Realizzato da</span>
          <img src={LOGO_REALIZZATORE} alt="Office Solution" />
        </div>
      </div>
    </div>
  );
}

